SET @prov_c := '%s';
SET @id:= '%s';
SET @cat_id := '%s';
SET @send :=  IF((SELECT active FROM sys_report WHERE cat_id = @cat_id and id = @id )=1,0,2);
SET @b_year:=(SELECT yearprocess FROM pk_byear LIMIT 1);
SET	@start_d:=concat(@b_year-1,'1001');
SET @end_d:=concat(@b_year,'0930');

CREATE TABLE IF NOT EXISTS s_kpi_dental15(
  id varchar(32) NOT NULL,
  hospcode varchar(5) NOT NULL,
  areacode varchar(8) NOT NULL,
  flag_sent varchar(1) DEFAULT NULL,
  date_com varchar(14) DEFAULT NULL,
  b_year varchar(4) NOT NULL,
	target int(9) DEFAULT 0,
	result int(9) DEFAULT 0,
	PRIMARY KEY (id,hospcode,areacode,b_year),
	KEY (hospcode),
	KEY (areacode),
	KEY (b_year)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

DELETE FROM s_kpi_dental15 WHERE id=@id AND b_year=(@b_year+543);

DROP TABLE IF EXISTS tmpz_providerdent;
CREATE TABLE IF NOT EXISTS tmpz_providerdent(
   PRIMARY KEY (cid)
) ENGINE=MyISAM DEFAULT CHARSET=utf8 IGNORE AS
SELECT p.* FROM provider p 
WHERE p.providertype in(2,6) AND p.OUTDATE is NULL
ORDER BY p.STARTDATE ASC
;

DROP TABLE IF EXISTS tmz_procedure_dental;
CREATE TEMPORARY TABLE tmz_procedure_dental (provider_cid varchar(13)  ,KEY(provider_cid)) ENGINE=myisam as
(SELECT
pr.*,p.cid provider_cid
FROM
 tmp_procedure_opd pr
INNER JOIN cwh_dent_icd10tm i ON pr.PROCEDCODE = i.icd10tm
LEFT JOIN provider p ON pr.hospcode=p.hospcode AND pr.provider=p.provider
WHERE p.providertype in(2,6)
);

INSERT IGNORE INTO s_kpi_dental15
(
SELECT
@id,p.hospcode 
,concat(h.provcode,SUBSTR(CONCAT('00',h.distcode),-2),SUBSTR(CONCAT('00',h.subdistcode),-2),SUBSTR(CONCAT('00',h.mu),-2)) as areacode
,@send,DATE_FORMAT(now(),'%Y%m%d%H%i') as d_com,@b_year+543 as b_year
,COUNT(DISTINCT IF(p.providertype in(2,6),CONCAT(p.hospcode,'-',p.provider),null)) target
,COUNT(DISTINCT pr.hospcode,pr.pid,seq) result
FROM
tmpz_providerdent p 
INNER JOIN chospital h ON h.hoscode=p.hospcode
LEFT JOIN tmz_procedure_dental pr ON p.cid=pr.provider_cid
WHERE 
h.provcode in(@prov_c) 
AND 
(pr.hospcode  IS NULL or pr.hospcode IS NOT NULL )
GROUP BY p.hospcode
);
